import type { Fact, WalkStep } from '@/app/demos/stage/types'

export const DEFAULT_BASE = 'https://example.com/page'
export const BASE = 'https://northwind.app/spring'

export const FIELDS = [
  { key: 'utm_source', value: 'newsletter', color: '#38bdf8' },
  { key: 'utm_medium', value: 'email', color: '#a78bfa' },
  { key: 'utm_campaign', value: 'spring_sale', color: '#fbbf24' },
  { key: 'utm_term', value: '', color: '#34d399' },
  { key: 'utm_content', value: 'hero_button', color: '#fb7185' },
]

/** Same order and skipping of empty fields as the extension. */
function build() {
  const url = new URL(BASE)
  FIELDS.forEach((field) => {
    if (field.value) url.searchParams.set(field.key, field.value)
  })
  return url.toString()
}

export const URL_OUT = build()
export const PIECES = FIELDS.filter((field) => field.value).map((field, index) => ({
  ...field,
  text: `${index === 0 ? '?' : '&'}${field.key}=${field.value}`,
}))

